def restore_bulk_grass_text(path, source):
    if str(path) != "src/data/wild_encounters.json":
        return source
    for label, old in ORIGINAL_BULK_GRASS.items():
        anchor='"base_label": "'+label+'"' 
        index=source.index('"mons": [',source.index(anchor))
        current=BALANCED_BULK_GRASS[label]
        assert source[index:index+len(current)]==current, label
        source=source[:index]+old+source[index+len(current):]
    return source

def prior_bulk_grass_source(path):
    return restore_bulk_grass_text(path,prior_mt_moon_source(path).decode("utf-8")).encode("utf-8")

def restore_prior_bulk_grass_text(path,source):
    return restore_bulk_grass_text(path,restore_prior_mt_moon_text(path,source))
